if(EditorApplication.isPlaying)throw new System.Exception("Edit mode required");
string folder="Assets/0_ProjectData/Player/Environment/Natural";if(!AssetDatabase.IsValidFolder(folder))AssetDatabase.CreateFolder("Assets/0_ProjectData/Player/Environment","Natural");
Mesh MakeRock(int seed){var rng=new System.Random(seed);int sides=12,rings=7;var vertices=new System.Collections.Generic.List<Vector3>();var uv=new System.Collections.Generic.List<Vector2>();var triangles=new System.Collections.Generic.List<int>();
 for(int j=0;j<rings;j++){float t=j/(float)(rings-1);float radius=j==0?.35f:j==rings-1?.13f:.48f*Mathf.Pow(Mathf.Sin(t*Mathf.PI),.45f);for(int i=0;i<=sides;i++){float a=i*Mathf.PI*2/sides;float warp=1+.1f*Mathf.Sin(a*3+seed)+.07f*Mathf.Cos(a*5+t*4);vertices.Add(new Vector3(Mathf.Cos(a)*radius*warp+.06f*Mathf.Sin(t*4+seed),t*1.12f-.035f+Mathf.Sin(a*3+seed)*.045f*Mathf.Sin(t*Mathf.PI),Mathf.Sin(a)*radius*warp));uv.Add(new Vector2(i/(float)sides,t));}}
 for(int j=0;j<rings-1;j++)for(int i=0;i<sides;i++){int n=j*(sides+1)+i;triangles.AddRange(new[]{n,n+sides+1,n+1,n+1,n+sides+1,n+sides+2});}
 int bottom=vertices.Count;vertices.Add(new Vector3(0,-.035f,0));uv.Add(Vector2.zero);int top=vertices.Count;vertices.Add(new Vector3(0,1.1f,0));uv.Add(Vector2.one);for(int i=0;i<sides;i++){triangles.AddRange(new[]{bottom,i,i+1,top,(rings-1)*(sides+1)+i+1,(rings-1)*(sides+1)+i});}
 var mesh=new Mesh{name="Weathered quarry boulder "+seed};mesh.SetVertices(vertices);mesh.SetUVs(0,uv);mesh.SetTriangles(triangles,0);mesh.RecalculateNormals();mesh.RecalculateBounds();Unwrapping.GenerateSecondaryUVSet(mesh);return mesh;}
var meshes=new Mesh[4];for(int i=0;i<4;i++){string path=folder+"/Boulder"+i+".asset";meshes[i]=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(!meshes[i]){meshes[i]=MakeRock(31+i*17);AssetDatabase.CreateAsset(meshes[i],path);}}
var rocks=UnityEngine.Object.FindObjectsByType<Bulldozer.Player.MineableRock>(FindObjectsSortMode.None).Where(r=>r.blockId.StartsWith("quarry-expansion-0-")).OrderBy(r=>r.blockId).Take(12).ToArray();
for(int i=0;i<rocks.Length;i++){var rock=rocks[i];Undo.RecordObject(rock.rockRenderer.GetComponent<MeshFilter>(),"Natural rock pilot");rock.name="Natural Boulder "+rock.blockId;var visual=rock.rockRenderer.transform;visual.localPosition=Vector3.zero;visual.localRotation=Quaternion.Euler(0,(i*47)%360,0);visual.localScale=new Vector3(1,.85f,1);rock.naturalBoulder=true;var embedded=visual.Find("Embedded Minerals");if(embedded)embedded.gameObject.SetActive(false);rock.rockRenderer.GetComponent<MeshFilter>().sharedMesh=meshes[i%4];rock.rockRenderer.lightmapIndex=-1;rock.rockRenderer.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.On;GameObjectUtility.SetStaticEditorFlags(visual.gameObject,0);var box=rock.GetComponent<BoxCollider>();box.center=new Vector3(0,.44f,0);box.size=new Vector3(.9f,.94f,.9f);var nav=rock.GetComponent<UnityEngine.AI.NavMeshObstacle>();if(nav){nav.center=box.center;nav.size=box.size;}if(rock.cracks)rock.cracks.SetActive(false);EditorUtility.SetDirty(rock);}
AssetDatabase.SaveAssets();UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(UnityEngine.SceneManagement.SceneManager.GetActiveScene());UnityEditor.SceneManagement.EditorSceneManager.SaveOpenScenes();
return new {rocks=rocks.Length,trianglesPerRock=meshes[0].triangles.Length/3,newMaterials=0};
